// ⓪ EL SOBRE · LA LLAVE · EL MODO SECO · CC#1 · 2026-10-01 · flujo `zero-risk/pieza` (el productor: un brief → una pieza).
// Este flujo PAGA (un agente). Por eso: (1) exige la llave de despacho del motor (lección E67: un POST con la marca copiada arrancaba una corrida paga),
// (2) exige `dry_run` EXPLÍCITO (true|false) · no se asume nunca, (3) TODO valor mal escrito detiene la corrida ANTES de gastar (ignorarlo dejaría pagar a ciegas).
// Agnóstico: sirve para cualquier cliente y cualquier brief de cualquier parte; nada de aquí nombra a un cliente.
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}

const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) {
  throw new Error('PIEZA_CERRADA · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo paga y queda cerrado hasta que exista · E67.')
}
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) {
  throw new Error('PIEZA_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo paga y solo lo despierta la sala · E67.')
}

const UUID = /^[0-9a-fA-F-]{36}$/
if (!body.client_id) throw new Error('PIEZA_SIN_CLIENTE · falta client_id en el sobre · se DETIENE y no escribe nada')
// los ids se pegan en direcciones de la base: solo un uuid o un identificador simple, nada más
if (!UUID.test(String(body.client_id))) throw new Error('PIEZA_CLIENTE_INVALIDO · client_id no es un uuid · se DETIENE y no escribe nada')
if (body.parte_id !== undefined && body.parte_id !== null && !UUID.test(String(body.parte_id))) {
  throw new Error('PIEZA_PARTE_INVALIDO · parte_id no es un uuid · se DETIENE y no escribe nada')
}
if (body.brief_id === undefined || body.brief_id === null || String(body.brief_id).trim() === '') {
  throw new Error('PIEZA_SIN_BRIEF · falta brief_id en el sobre (el identificador del brief dentro del parte, p. ej. BRF-0006) · se DETIENE y no escribe nada')
}
if (!/^[A-Za-z0-9_-]{3,40}$/.test(String(body.brief_id))) {
  throw new Error('PIEZA_BRIEF_INVALIDO · brief_id debe ser un identificador simple (letras, números, guion) de 3 a 40 caracteres · llegó ' + JSON.stringify(body.brief_id) + ' · se DETIENE y no escribe nada')
}
if (typeof body.dry_run !== 'boolean') {
  throw new Error('PIEZA_DRY_RUN_AUSENTE · el sobre debe traer dry_run explícito (true o false) · no se asume · se DETIENE antes de gastar')
}

// TOPE DURO por llamada (US$) · el corredor se lo pasa al SDK y CORTA al alcanzarlo. Ausente ⇒ el de fábrica: 0,60 (cota del peor caso de UNA pieza con fotos y herramienta:
// el máximo medido de este agente 0,383 + las fotos ≈0,09 + lo que devuelva «mirar afuera» ≈0,04 + vueltas con caché ≈0,04 ≈ 0,56 · es una COTA, no una medición).
// Presente ⇒ número > 0 y ≤ 50; un tope MAL ESCRITO detiene antes de gastar.
const TOPE_DE_FABRICA_USD = 0.6
let tope_usd = TOPE_DE_FABRICA_USD
let tope_de_fabrica = true
if (body.tope_usd !== undefined) {
  const n = typeof body.tope_usd === 'number' ? body.tope_usd : (typeof body.tope_usd === 'string' && body.tope_usd.trim() !== '' ? Number(body.tope_usd) : NaN)
  if (!Number.isFinite(n) || n <= 0 || n > 50) {
    throw new Error('PIEZA_TOPE_INVALIDO · tope_usd debe ser un número mayor que 0 y hasta 50 · llegó ' + JSON.stringify(body.tope_usd) + ' · se DETIENE antes de gastar: ignorarlo dejaría pagar sin tope')
  }
  tope_usd = n
  tope_de_fabrica = false
}

return [{
  json: {
    client_id: String(body.client_id),
    tenant_id: body.tenant_id || body.client_id,
    parte_id: body.parte_id ? String(body.parte_id) : null,
    brief_id: String(body.brief_id),
    dry_run: body.dry_run,
    forzar: body.forzar === true || body.force_restart === true,
    desde_worker: body.desde_worker || null,
    _sala_correlation_id: body._sala_correlation_id || null,
    _journey_id: body._journey_id || null,
    // SOLO en modo seco: una respuesta del productor enlatada para ejercitar los chequeos con datos de forma real sin pagar. En modo real se IGNORA.
    simulacro_respuesta: body.dry_run === true && typeof body._simulacro_respuesta === 'string' ? body._simulacro_respuesta : null,
    tope_usd,
    tope_de_fabrica,
  },
}]

// ① GUARDA · el parte y el brief · CC#1 · 2026-10-01. Sin parte VÁLIDO, o sin ese brief dentro de él, se DETIENE y no se escribe nada.
// El brief se lee ESTRUCTURADO de `provenance_tag.parte` (lo guarda el flujo del brief junto al texto), no se parsea de un texto pegado a mano.
const env = $('⓪ Sobre · llave · modo seco').first().json
// 🔴 UN ERROR DE LA BASE NO ES «VACÍO» (certificación CC#3 · 01-oct): el nodo HTTP de la consulta tiene `onError: continueRegularOutput` y, si la base falla, entrega un ítem `{error:{…}}`
// (o PostgREST contesta un OBJETO `{code, message}` en vez de una lista). Leerlo como «sin parte» seguiría hacia el nodo que PAGA. Se DETIENE con su motivo.
const _filas = $input.all().map((i) => i.json)
const _falla = _filas.find((r) => r && ((r.error !== undefined && r.error !== null) || (r.code !== undefined && r.message !== undefined && r.id === undefined)))
if (_falla) {
  const _m = _falla.error && typeof _falla.error === 'object' ? (_falla.error.message || _falla.error.name) : (_falla.error || _falla.message)
  throw new Error('PIEZA_PARTE_CONSULTA_FALLO · la consulta a la base FALLÓ (' + String(_m || 'sin detalle').slice(0, 160) + ') · un error no es «sin parte» · se DETIENE y NO escribe nada')
}
const filas = $input.all().map((i) => i.json).filter((r) => r && r.id)
if (filas.length === 0) {
  throw new Error('PIEZA_SIN_PARTE · el cliente ' + env.client_id + ' no tiene un parte de trabajo (campaign_brief_pack) · se DETIENE y NO escribe nada')
}
const esNoValido = (r) => String(r.title || '').indexOf('⛔') === 0 || (r.provenance_tag && r.provenance_tag.valido === false)
let parte
if (env.parte_id) {
  parte = filas.find((r) => r.id === env.parte_id)
  if (!parte) throw new Error('PIEZA_PARTE_INEXISTENTE · el parte ' + env.parte_id + ' no existe para el cliente ' + env.client_id + ' · se DETIENE y NO escribe nada')
  if (esNoValido(parte)) throw new Error('PIEZA_PARTE_NO_VALIDO · el parte ' + parte.id + ' está marcado como NO VÁLIDO · no se produce una pieza desde un parte inválido · se DETIENE y NO escribe nada')
} else {
  parte = filas.find((r) => !esNoValido(r))
  if (!parte) throw new Error('PIEZA_PARTE_NO_VALIDO · todos los partes del cliente están marcados NO VÁLIDOS · se DETIENE y NO escribe nada')
}
const p = parte.provenance_tag && typeof parte.provenance_tag === 'object' ? parte.provenance_tag : {}
const estructurado = p.parte && typeof p.parte === 'object' ? p.parte : null
if (!estructurado || !Array.isArray(estructurado.entregables)) {
  throw new Error('PIEZA_PARTE_ILEGIBLE · el parte ' + parte.id + ' no trae su lista de entregables estructurada (provenance_tag.parte) · se DETIENE y NO escribe nada')
}
const brief = estructurado.entregables.find((e) => e && String(e.id) === env.brief_id)
if (!brief) {
  const hay = estructurado.entregables.map((e) => e && e.id).filter(Boolean).join(', ') || '(ninguno)'
  throw new Error('PIEZA_BRIEF_INEXISTENTE · el parte ' + parte.id + ' no tiene el brief ' + env.brief_id + ' · tiene: ' + hay + ' · se DETIENE y NO escribe nada')
}
const lista = (v) => (Array.isArray(v) && v.length ? v.map((x) => '  - ' + x).join('\n') : '  (ninguno)')
const vis = brief.visual
const L = []
L.push('BRIEF ' + brief.id + ' · ' + (brief.plataforma || '?') + ' · ' + (brief.tipo_de_pieza || '?'))
L.push('- QUÉ ES: ' + (brief.que_es || ''))
L.push('- DE QUÉ PARTE DEL PLAN SALE: ' + (brief.de_que_parte_del_plan || ''))
L.push('- OBJETIVO: ' + (brief.objetivo || ''))
L.push('- SEGMENTO: ' + (brief.segmento || ''))
L.push('- PROTAGONISTA: ' + (brief.protagonista || ''))
L.push('- MENSAJE (uno): ' + (brief.mensaje || ''))
L.push('- HIPÓTESIS: ' + (brief.hipotesis || ''))
L.push('- LÍMITES: ' + (brief.limites || ''))
L.push('- VOCABULARIO OBLIGATORIO:\n' + lista(brief.vocabulario_obligatorio))
L.push('- PROHIBIDO:\n' + lista(brief.prohibido))
L.push('- SINTAXIS: ' + (brief.sintaxis || ''))
L.push('- VISUAL: ' + (vis && typeof vis === 'object' ? 'capa que manda: ' + (vis.capa_que_manda || '?') + ' · ' + (vis.descripcion || '') + ' · MUESTRA: ' + (vis.muestra || '(sin muestra)') : String(vis || '')))
L.push('- LLAMADO A LA ACCIÓN: ' + (brief.llamado_a_la_accion || ''))
L.push('- VARIANTES: ' + (brief.variantes || ''))
L.push('- NEGATIVOS:\n' + lista(brief.negativos))
L.push('- APRUEBA Y PARA CUÁNDO: ' + (brief.aprueba_y_para_cuando || ''))
return [{
  json: {
    ...env,
    parte_id: parte.id,
    parte_creado: parte.created_at,
    plan_id: p.plan_id || null,
    manual_id_del_parte: p.manual_id || null,
    brief,
    brief_texto: L.join('\n'),
    plataforma: brief.plataforma || null,
    tipo_de_pieza: brief.tipo_de_pieza || null,
    // 03-oct · EL PRODUCTO: el protagonista de ESTE brief (y su vocabulario obligatorio, que ya viaja dentro de `brief`) · ③ y ⑤ lo usan para saber qué muestra cada foto
    protagonista: brief.protagonista || null,
  },
}]

// ② GUARDA · sin manual APROBADO se DETIENE · CC#1 · 2026-10-01. El manual aporta las palabras prohibidas para los chequeos (el brief ya trae las suyas).
const prev = $('① GUARDA · el parte y el brief').first().json
// 🔴 UN ERROR DE LA BASE NO ES «VACÍO» (certificación CC#3 · 01-oct): el nodo HTTP de la consulta tiene `onError: continueRegularOutput` y, si la base falla, entrega un ítem `{error:{…}}`
// (o PostgREST contesta un OBJETO `{code, message}` en vez de una lista). Leerlo como «sin manual» seguiría hacia el nodo que PAGA. Se DETIENE con su motivo.
const _filas = $input.all().map((i) => i.json)
const _falla = _filas.find((r) => r && ((r.error !== undefined && r.error !== null) || (r.code !== undefined && r.message !== undefined && r.id === undefined)))
if (_falla) {
  const _m = _falla.error && typeof _falla.error === 'object' ? (_falla.error.message || _falla.error.name) : (_falla.error || _falla.message)
  throw new Error('PIEZA_MANUAL_CONSULTA_FALLO · la consulta a la base FALLÓ (' + String(_m || 'sin detalle').slice(0, 160) + ') · un error no es «sin manual» · se DETIENE y NO escribe nada')
}
const filas = $input.all().map((i) => i.json).filter((r) => r && r.id)
if (filas.length === 0) {
  throw new Error('PIEZA_SIN_MANUAL · el cliente ' + prev.client_id + ' no tiene manual de marca · se DETIENE y NO escribe nada')
}
const m = filas[0]
if (m.gate_outcome !== 'paso_la_vara') {
  throw new Error('PIEZA_MANUAL_NO_APROBADO · manual ' + m.id + ' con gate_outcome=' + JSON.stringify(m.gate_outcome) + ' · se DETIENE y NO escribe nada')
}
return [{
  json: {
    ...prev,
    manual_id: m.id,
    manual_version: m.version,
    forbidden_words: Array.isArray(m.forbidden_words) ? m.forbidden_words : [],
    required_terminology: Array.isArray(m.required_terminology) ? m.required_terminology : [],
    // 03-oct · EL TRATO (tú · vos · usted) sale del manual: su descripción de voz y sus guías de tono viajan a ⑤ y ⑦
    manual_voz: { voice_description: m.voice_description || null, writing_style: m.writing_style || null, tone_guidelines: m.tone_guidelines && typeof m.tone_guidelines === 'object' ? m.tone_guidelines : {} },
    manual_distinto_del_parte: !!(prev.manual_id_del_parte && prev.manual_id_del_parte !== m.id),
  },
}]

/**
 * CADA FOTO VIAJA CON TODO SU CONTEXTO · CC#1 · 2026-10-03 · encargo Lenovo «cada foto viaja con todo su contexto».
 *
 * Lógica PURA (sin red, sin `this`, sin `URL`, sin `require`): la usan el Servicio de Apify (copia de fotos), el flujo de la pieza (③ ⑤ ⑦), el completador de filas viejas y las pruebas.
 * Se pega entera en los nodos Code de n8n (como `sedes-logica.js`): por eso va en estilo `var` + `function`.
 *
 * 🔴 ESTRUCTURAL, NUNCA POR CLIENTE: ninguna lista de platos, ni de clientes, ni de ciudades. El «producto» de una foto sale del TEXTO del post, comparado con los productos que el
 * propio cliente declara en su plan (los `protagonista` de sus briefs). Lo que no se puede afirmar se declara «desconocido»: nunca se adivina.
 */

// ───────────────────────────── texto ─────────────────────────────
function sinTildes(s) {
  return String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
}
function limpiar(s, max) {
  var t = String(s === undefined || s === null ? '' : s).replace(/\s+/g, ' ').trim()
  return max && t.length > max ? t.slice(0, max).replace(/\s+\S*$/, '') + '…' : t
}

// palabras de función (español e inglés) y palabras de marketing tan genéricas que no nombran un producto · NO son platos ni marcas: son del idioma
var VACIAS = ('para como esta este esto estos estas esos esas pero porque cuando donde desde hasta entre sobre tambien solo todo toda todos todas cada otro otra otros otras mismo misma muy mas menos ' +
  'que con sin por una unos unas del los las nos les sus tus mis the and for with that this from your you are our not hace hacer tiene tener puede pueden ser son fue era hay aqui alla').split(' ')
var GENERICAS = ('plato platos producto productos servicio servicios marca oferta ofertas promo promocion promociones linea opcion opciones nuevo nueva nuevos nuevas principal especial origen calidad foto fotos imagen ' +
  'pieza cliente negocio local menu carta mejor mejores verdadero verdadera delicioso deliciosa sabor sabores ' +
  'disponibilidad ficha experiencia pedido alma precio precios historia narrativa comunidad horario horarios ciudad direccion telefono informacion mensaje respuesta cuenta resena voz etiqueta accion anuncio fase ' +
  'operativa operativo verificada verificado correcta correcto concreta concreto completo completa existente primer primera').split(' ')

function raiz(w) {
  var t = w.replace(/(es|s)$/, '')
  return t.length > 6 ? t.slice(0, 6) : t
}
/** las palabras significativas de un texto con su raíz: [{ palabra, raiz }] · sin @menciones · las #etiquetas SÍ cuentan (dicen el producto) · `excluir` = raíces que no pueden ser producto (marca, ciudad, usuario) */
function significativas(texto, excluir) {
  var ex = {}
  ;(excluir || []).forEach(function (r) { ex[r] = true })
  var t = sinTildes(texto).replace(/@[a-z0-9._]+/g, ' ').replace(/#/g, ' ')
  var out = []
  var vistas = {}
  t.split(/[^a-z0-9]+/).forEach(function (w) {
    if (w.length < 4 || VACIAS.indexOf(w) !== -1 || GENERICAS.indexOf(w) !== -1) return
    var r = raiz(w)
    if (ex[r] || vistas[r]) return
    vistas[r] = true
    out.push({ palabra: w, raiz: r })
  })
  return out
}
function raicesDe(texto, excluir) {
  return significativas(texto, excluir).map(function (s) { return s.raiz })
}
/** raíces que NO pueden nombrar un producto: la marca, su usuario, las ciudades/mercado/país de la ficha */
function excluirDe(datos) {
  var d = datos || {}
  var textos = [d.nombre].concat(d.handles || [], d.ciudades || [], [d.market, d.country])
  var out = []
  textos.forEach(function (x) { raicesDe(x, []).forEach(function (r) { if (out.indexOf(r) === -1) out.push(r) }) })
  return out
}

// ───────────────────────────── el producto del brief y los del cliente ─────────────────────────────
/** «La pizza con su origen en Parma. UNO. No la focaccia, no el combo.» → lo que el brief PIDE: se quita todo desde cada negación hasta el fin de la frase */
function sinNegaciones(texto) {
  return sinTildes(texto).replace(/\b(no|ni|sin|nunca|jamas|not|never)\b[^.;\n]*/g, ' ')
}
/** { nombre, raices[] } o null si el texto no nombra nada que pueda ser un producto */
function entradaDeProtagonista(protagonista, excluir) {
  var sig = significativas(sinNegaciones(protagonista), excluir)
  if (!sig.length) return null
  // el nombre del producto son SUS palabras («pizza»), no la frase entera del brief
  return { nombre: sig.map(function (s) { return s.palabra }).join(' '), raices: sig.map(function (s) { return s.raiz }) }
}
/**
 * EL PRODUCTO DE UN BRIEF = las palabras de su `protagonista` que su `vocabulario_obligatorio` también dice (el brief ya declara así su producto: «pizza» está en las dos).
 * Sin vocabulario: la primera palabra significativa. Si el protagonista y el vocabulario no comparten ningún término, el brief NO nombra un producto: devuelve null (no se inventa una regla).
 */
function productoDelBrief(brief, excluir) {
  var b = brief || {}
  var S = significativas(sinNegaciones(b.protagonista), excluir)
  if (!S.length) return null
  var vocab = Array.isArray(b.vocabulario_obligatorio) ? b.vocabulario_obligatorio.filter(function (x) { return typeof x === 'string' && x.trim() }) : []
  if (vocab.length) {
    var V = raicesDe(vocab.join(' . '), [])
    S = S.filter(function (s) { return V.indexOf(s.raiz) !== -1 })
    if (!S.length) return null
  } else S = S.slice(0, 1)
  return { nombre: S.map(function (s) { return s.palabra }).join(' '), raices: S.map(function (s) { return s.raiz }) }
}
/**
 * LAS ALTERNATIVAS que el propio brief nombra al negarlas: «No el X, no el Y, no la historia…» → X e Y (la primera palabra de cada cláusula negada · si es abstracta —historia, precio— no cuenta).
 * Es lo que el autor del brief dice que NO es el protagonista: la fuente más precisa de «otro producto» que hay sin una lista fija.
 */
function alternativasDelBrief(brief, excluir, producto) {
  var t = sinTildes((brief || {}).protagonista)
  var ex = {}
  ;(excluir || []).forEach(function (r) { ex[r] = true })
  var vistas = {}
  ;((producto && producto.raices) || []).forEach(function (r) { vistas[r] = true })
  var out = []
  var re = /\b(?:no|ni|sin|nunca|jamas)\s+(?:el|la|los|las|un|una|unos|unas)\s+([^,.;\n]+)/g
  var m
  while ((m = re.exec(t)) !== null) {
    var w = (m[1].split(/[^a-z0-9]+/).filter(Boolean)[0]) || ''
    if (w.length < 4 || VACIAS.indexOf(w) !== -1 || GENERICAS.indexOf(w) !== -1) continue
    var r = raiz(w)
    if (ex[r] || vistas[r]) continue
    vistas[r] = true
    out.push({ nombre: w, raices: [r] })
  }
  return out
}
/** el catálogo con que se mira cada foto de ESTE brief: sus alternativas + los productos que el DUEÑO declara en la ficha (`config.productos`) · el producto del brief va aparte */
function catalogoDelBrief(brief, producto, ficha, excluir) {
  var cat = alternativasDelBrief(brief, excluir, producto)
  var cfg = ficha && ficha.config && typeof ficha.config === 'object' ? ficha.config : {}
  var vistas = {}
  cat.forEach(function (e) { e.raices.forEach(function (r) { vistas[r] = true }) })
  ;((producto && producto.raices) || []).forEach(function (r) { vistas[r] = true })
  ;(Array.isArray(cfg.productos) ? cfg.productos : []).forEach(function (s) {
    var e = entradaDeProtagonista(s, excluir)
    if (e && !e.raices.every(function (r) { return vistas[r] })) { e.raices.forEach(function (r) { vistas[r] = true }); cat.push(e) }
  })
  return cat
}
/** los productos del propio cliente: el protagonista de cada brief de su plan · se quitan las raíces comunes a TODOS (no distinguen un producto de otro) */
function catalogoDeProtagonistas(protagonistas, excluir) {
  var entradas = []
  var vistos = {}
  ;(protagonistas || []).forEach(function (p) {
    var e = entradaDeProtagonista(p, excluir)
    if (!e) return
    var k = e.raices.slice().sort().join('|')
    if (vistos[k]) return
    vistos[k] = true
    entradas.push(e)
  })
  if (entradas.length > 1) {
    var comunes = entradas[0].raices.filter(function (r) { return entradas.every(function (e) { return e.raices.indexOf(r) !== -1 }) })
    entradas.forEach(function (e) {
      var resto = e.raices.filter(function (r) { return comunes.indexOf(r) === -1 })
      if (resto.length) e.raices = resto
    })
  }
  return entradas
}
/** ¿qué productos del catálogo nombra este texto? → { producto: [nombres], fuente: 'caption' | 'desconocido', evidencia: [raíces] } */
function productoDeTexto(texto, catalogo) {
  var n = nombrados(catalogo, texto)
  if (!n.entradas.length) return { producto: [], fuente: 'desconocido', evidencia: [] }
  var evidencia = []
  n.entradas.forEach(function (e) { n.raicesTocadas.forEach(function (x) { if (e.raices.indexOf(x) !== -1 && evidencia.indexOf(x) === -1) evidencia.push(x) }) })
  return { producto: n.entradas.map(function (e) { return e.nombre }), fuente: 'caption', evidencia: evidencia, via: n.via }
}
/**
 * Qué entradas (productos) NOMBRA un texto. 🔴 EL CUERPO MANDA SOBRE LAS ETIQUETAS: una cola de #etiquetas suele meter cualquier plato por alcance («#pizza» en el post de otra receta).
 * Si el cuerpo nombra alguno, SÓLO cuentan los del cuerpo; las etiquetas se usan únicamente cuando el cuerpo no nombra ninguno.
 */
function partesDelTexto(texto) {
