function resolverSedes(sedes, observaciones) {
  observaciones = ultimasPorFuente(observaciones || [])
  return (sedes || []).map(function (s) {
    var propias = observaciones.filter(function (o) { return o.sede === s.clave && o.campo !== 'ciudad' })
