    var k = clave(t).slice(0, 60)
    if (vistos[k]) continue
    vistos[k] = true
    out.push({ fecha: p.timestamp ? String(p.timestamp).slice(0, 10) : null, texto: t.length > largo ? t.slice(0, largo).replace(/\s+\S*$/, '') + '…' : t, post: p.shortCode || null })
