    const mismosPermitidos = eco && Array.isArray(eco.permitidos) && Array.isArray(pedidos.permitidos) && eco.permitidos.length === pedidos.permitidos.length && pedidos.permitidos.every((x) => eco.permitidos.indexOf(x) !== -1)
