if (!ext.legible && c.llego_la_vuelta) {
  P.push('')
  P.push('## ⚠️ Respuesta del productor (no legible como pieza · se guarda tal cual para diagnóstico)')
  P.push(String(c.texto || '').slice(0, 6000))
}
if (c.texto_parcial) {
