  // el producto del brief va primero (si hay que recortar, no se pierde la foto que importa) · dentro de cada rol, el orden de entrada (las más nuevas primero)
  var peso = { producto_del_brief: 0, sin_regla: 1, no_identificado: 2, varios_productos: 2, otro_producto: 3, marca: 4 }
  var ordenadas = fotos.map(function (f, i) { return { f: f, i: i } }).sort(function (a, b) { return (peso[a.f.rol] + (a.f.parcial ? 0.5 : 0)) - (peso[b.f.rol] + (b.f.parcial ? 0.5 : 0)) || a.i - b.i }).map(function (x) { return x.f })
  var enviadas = ordenadas.slice(0, max)
  var no_enviadas = ordenadas.slice(max).map(function (f) { return f.id || f.post_id })
  enviadas.forEach(function (f, i) { f.ref = 'F' + ('0' + (i + 1)).slice(-2); f.label = etiquetaDeFoto(f) })
  var reglaActiva = !!prot
  return {
    regla_activa: reglaActiva,
    producto_del_brief: prot ? prot.nombre : null,
    raices_del_producto: prot ? prot.raices : [],
    fotos: enviadas, no_enviadas: no_enviadas, duplicadas_ocultas: duplicadas,
    de_referencia: enviadas.filter(function (f) { return f.rol === 'producto_del_brief' }).map(function (f) { return f.ref }),
    sin_foto_del_producto: reglaActiva && !enviadas.some(function (f) { return f.rol === 'producto_del_brief' }),
  }
}

/** ≤ 80 caracteres (el límite del corredor): «F08 · 2025-10-12 · ES el producto: pizza» */
function etiquetaDeFoto(f) {
  var quien = f.rol === 'producto_del_brief' ? (f.parcial ? 'ES el producto (coincide en parte)' : 'ES el producto')
    : f.rol === 'otro_producto' ? 'NO es el producto: ' + productosDe(f).join(' + ')
    : f.rol === 'no_identificado' ? 'producto sin identificar'
    : f.rol === 'varios_productos' ? 'varios productos en el texto'
    : f.rol === 'marca' ? 'logo de la marca'
    : (NOMBRE_MEDIO[f.medio] || 'foto')
  var debil = f.via === 'etiqueta' && (f.rol === 'producto_del_brief' || f.rol === 'otro_producto') ? ' (sólo #etiqueta)' : ''
  return (f.ref + ' · ' + (f.fecha || 's/f') + ' · ' + quien + debil).slice(0, 80)
}

/** el bloque B del pedido: CADA foto con su texto, fecha y enlace · y la regla del producto */
function bloqueDeFotos(clasif, nombre) {
  var fotos = clasif.fotos
  if (!fotos.length) {
    return ['B) LAS FOTOS REALES DEL NEGOCIO. Para este cliente NO hay fotos propias disponibles. No las inventes: escribe el prompt de imagen solo desde el brief y declara en',
      '   «no_pude_cumplir» que no hubo fotos reales de apoyo. En «foto_referencia» pon null.'].join('\n')
  }
  var L = ['B) LAS FOTOS REALES DEL NEGOCIO. Van adjuntas a este mensaje: son ' + fotos.length + ' foto' + (fotos.length === 1 ? '' : 's') + ' propias de ' + nombre + '. Cada una lleva una clave (F01, F02…): la clave está en la etiqueta de la foto.',
    '   Aquí abajo está TODO lo que el sistema sabe de cada una: de qué publicación sale, cuándo, el texto con que el dueño la publicó y qué producto nombra ese texto.']
  fotos.forEach(function (f) {
    var donde = f.medio === 'logo' ? 'logo de la marca' : (NOMBRE_MEDIO[f.medio] || 'foto') + ' · ' + nombreDePosicion(f)
    var que = f.rol === 'producto_del_brief' ? (f.parcial ? 'coincide sólo en parte con «' + clasif.producto_del_brief + '» (el texto no nombra todo el producto: puede ser otra variante o sólo una etiqueta · mírala con cuidado)' : 'ES el producto del brief')
      : f.rol === 'otro_producto' ? 'NO es el producto del brief (el texto nombra: ' + productosDe(f).join(' + ') + ')'
      : f.rol === 'no_identificado' ? 'el texto no nombra un producto: NO se sabe qué plato es'
      : f.rol === 'varios_productos' ? 'el texto nombra varios productos (' + productosDe(f).join(' + ') + '): NO se sabe cuál muestra la foto'
      : f.rol === 'marca' ? 'logo'
      : 'sin regla de producto'
    L.push('   ' + f.ref + ' · ' + donde + ' · ' + (f.fecha || 'sin fecha') + (f.enlace ? ' · ' + f.enlace : '') + ' · texto de la publicación: ' + (f.texto ? '«' + limpiar(f.texto, 240) + '»' : '(sin texto)') + ' · ' + que + ' (según ' + (f.producto_fuente === 'dueno' ? 'el dueño' : f.producto_fuente === 'caption' ? (f.via === 'etiqueta' ? 'una #etiqueta: el cuerpo del texto NO lo dice · evidencia débil' : 'el texto de la publicación') : 'nadie') + ')')
  })
  if (clasif.no_enviadas.length) L.push('   (No caben ' + clasif.no_enviadas.length + ' foto(s) más en este pedido: ' + clasif.no_enviadas.join(', ') + ')')
  // 🔴 CANON «SIN REJAS AL AGENTE» (Emilio · 03-oct): el productor crea LIBRE; lo de arriba es INFORMACIÓN sobre lo que muestra cada foto, no una regla. El control es la aprobación de Emilio antes de publicar.
  var LIBRE = 'Eres LIBRE de usar de referencia CUALQUIER foto (propia, de otro producto, de la competencia) y de alterarla, o de crear la imagen sin ninguna foto: las etiquetas de arriba son información, no una regla.'
  if (!clasif.regla_activa) {
    L.push('   Míralas todas antes de escribir el prompt de imagen. ' + LIBRE,
      '   En «foto_referencia» pon la clave de la foto que usaste de referencia y por qué (o null si no usaste ninguna).')
  } else if (clasif.sin_foto_del_producto) {
    L.push('   El producto de este brief es «' + clasif.producto_del_brief + '». Hoy no hay ninguna foto que su texto asocie a «' + clasif.producto_del_brief + '» (las de arriba son de otros platos o de ninguno). ' + LIBRE,
      '   En «foto_referencia» pon la clave de la foto que usaste y por qué, o null si creaste la imagen sin foto.')
  } else {
    L.push('   El producto de este brief es «' + clasif.producto_del_brief + '». Las fotos cuyo texto lo asocia a él: ' + clasif.de_referencia.join(', ') + '. ' + LIBRE,
      '   En «foto_referencia» pon la clave de la foto que usaste y por qué (una frase).')
  }
  L.push('   Si el brief pide algo que la foto de referencia no muestra, puedes agregarlo o alterar la foto: dilo en «fuera_de_la_foto» (es información para quien aprueba).')
  return L.join('\n')
}

// ───────────────────────────── el chequeo (determinista · sin modelo) ─────────────────────────────
/** La clave de foto que declara la pieza: «F08» o { foto: 'F08', por_que } · null si declaró «ninguna» */
function fotoDeclarada(pieza) {
  var v = pieza && pieza.foto_referencia
  var s = v && typeof v === 'object' ? v.foto : v
  s = typeof s === 'string' ? s.trim().toUpperCase() : ''
  return /^F\d{2}$/.test(s) ? s : null
}
/**
 * INFORMACIÓN para quien aprueba, NUNCA una reja (canon «sin rejas al agente»): ningún hallazgo de aquí es fatal.
 * `ctx` = { regla_activa, sin_foto_del_producto, producto_del_brief, fotos: [{ref, rol, producto}] } · devuelve [{ chequeo, detalle, fatal:false }]
 */
function chequearFotoReferencia(pieza, ctx, brief) {
  var h = []
  if (!ctx || !ctx.regla_activa) return h
  var falla = function (chequeo, detalle) { h.push({ chequeo: chequeo, detalle: detalle, fatal: false }) }
  var tipo = sinTildes(brief && brief.tipo_de_pieza)
  if (tipo !== 'imagen' && tipo !== 'carrusel') return h
  var prompt = String((pieza && pieza.prompt_imagen) || '')
  var fuente = String((pieza && pieza.fuente_imagen) || '')
  var ref = fotoDeclarada(pieza)
  var foto = ref ? (ctx.fotos || []).filter(function (f) { return f.ref === ref })[0] : null
  if (ref && !foto) falla('foto_referencia_inexistente', 'la pieza declara la foto «' + ref + '» de referencia y esa clave no existe entre las fotos que se le dieron')
  if (foto && foto.rol === 'otro_producto') falla('foto_referencia_de_otro_producto', 'la foto de referencia declarada (' + ref + ') muestra «' + (foto.producto || []).join(' + ') + '» y el producto del brief es «' + ctx.producto_del_brief + '» · informativo: el productor puede usar cualquier foto y alterarla; lo decide quien aprueba')
  else if (foto && (foto.rol === 'no_identificado' || foto.rol === 'varios_productos')) falla('foto_referencia_sin_producto_identificado', 'la foto de referencia declarada (' + ref + ') no tiene un producto identificado: el sistema no puede decir qué plato muestra')
  if (!ctx.sin_foto_del_producto && fuente === 'cliente' && prompt.trim() && !ref) falla('foto_referencia_no_declarada', 'la imagen es del cliente y la pieza no declara qué foto usó de referencia')
  return h
}

// ───────────────────────────── LO QUE LA FOTO NO MUESTRA (información para quien aprueba)
/**
 * Si el brief pide algo que la foto de referencia no muestra, el productor puede agregarlo o alterar la foto: lo DECLARA en `fuera_de_la_foto`. Avisos (nunca fatales); sólo si la imagen sale de una foto del cliente.
 * (Canon «sin rejas al agente»: ya no existe ningún chequeo de marcas, rótulos ni contactos en el prompt de imagen.)
 */
function chequearLoQueLaFotoNoMuestra(pieza) {
  var h = []
  var falla = function (chequeo, detalle) { h.push({ chequeo: chequeo, detalle: detalle, fatal: false }) }
  var prompt = String((pieza && pieza.prompt_imagen) || '')
  var fuente = String((pieza && pieza.fuente_imagen) || '')
  if (!prompt.trim() || fuente !== 'cliente') return h
  var fuera = pieza && pieza.fuera_de_la_foto
  if (!Array.isArray(fuera)) {
    falla('no_declaro_lo_que_la_foto_no_muestra', 'la imagen es del cliente y la pieza no trae la lista «fuera_de_la_foto» (aunque sea vacía): no se sabe si lo que pide el brief sale de la foto o se agregó')
  } else if (fuera.length) {
    falla('foto_no_muestra_lo_que_pide_el_brief', 'el brief pide y la foto de referencia NO muestra: ' + fuera.slice(0, 6).map(function (x) { return '«' + x + '»' }).join(' · ') + ' · informativo: el productor lo agregó o alteró la foto')
    var noPude = raicesDe([].concat((pieza && pieza.no_pude_cumplir) || []).map(String).join(' . '), [])
    var sin = fuera.filter(function (x) { var r = raicesDe(x, []); return r.length && !r.some(function (y) { return noPude.indexOf(y) !== -1 }) })
    if (sin.length) falla('elemento_fuera_de_la_foto_sin_declarar', 'lo que la foto no muestra (' + sin.slice(0, 4).map(function (x) { return '«' + x + '»' }).join(' · ') + ') no está repetido en «no_pude_cumplir»')
  }
  return h
}

// ───────────────────────────── la pasada de VISIÓN · DISEÑADA Y APAGADA ─────────────────────────────
// 🔴 NO se construye con gasto (encargo Lenovo punto 3): requiere el GO de Emilio. Este módulo NO tiene red ni llamada a ningún modelo: sólo el CONTRATO y la regla de combinación,
// para que cuando haya GO la pasada sea enchufar un ejecutor y no rediseñar. Sin autorización explícita, `planDeVision` devuelve «apagada» y NO prepara ningún pedido.
//
// Diseño: una llamada pequeña por foto (UNA vez por huella: la misma imagen no se paga dos veces) que responde CONTRA EL CATÁLOGO del cliente (los productos de su plan), no contra una lista fija de platos:
//   entrada  → { foto: url del bucket, catalogo: [nombres de producto del cliente] }
//   salida   → { producto: <un nombre del catálogo> | 'ninguno' | 'no_se', seguridad: 0..1 }
// Combinación con el texto del post (`combinarFuentes`): el dueño GANA · texto y visión de acuerdo ⇒ 'caption' (con la visión de respaldo) · sólo uno habla ⇒ ése · chocan ⇒ 'conflicto' y NO se usa.
var VISION_ENCENDIDA = false
function planDeVision(filas, catalogo, autorizacion) {
  var pendientes = (filas || []).filter(function (f) { return f && !f.duplicado_de && !esLogo(f) && f.producto_fuente !== 'dueno' && f.producto_fuente !== 'vision' && !tieneProducto(f) })
  if (VISION_ENCENDIDA !== true || !autorizacion || autorizacion.go_emilio !== true) {
    return { estado: 'apagada', motivo: 'la pasada de visión requiere el GO de Emilio (gasto por foto) · no se prepara ningún pedido', pendientes: pendientes.length, pedidos: [] }
  }
  return { estado: 'autorizada_sin_ejecutor', pendientes: pendientes.length, pedidos: pendientes.map(function (f) { return { id: f.id, url: f.url, catalogo: (catalogo || []).map(function (e) { return e.nombre }) } }) }
}
/** { producto: [nombres], fuente } de lo que dicen el texto del post (`caption`), la visión (`vision`) y el dueño (`dueno`) · cada uno es { producto: [nombres] } o null */
function combinarFuentes(caption, vision, dueno) {
  var norm = function (v) { return v && Array.isArray(v.producto) ? v.producto.map(function (x) { return String(x).toLowerCase().trim() }).filter(Boolean).sort() : [] }
  var d = norm(dueno), c = norm(caption), v = norm(vision)
  if (d.length) return { producto: dueno.producto, fuente: 'dueno' }
  if (c.length && v.length) return c.join('|') === v.join('|') ? { producto: caption.producto, fuente: 'caption' } : { producto: [], fuente: 'conflicto' }
  if (c.length) return { producto: caption.producto, fuente: 'caption' }
  if (v.length) return { producto: vision.producto, fuente: 'vision' }
  return { producto: [], fuente: 'desconocido' }
}


/**
 * EL TRATO (tú · vos · usted) ES DE LA MARCA, NO UNA REGLA FIJA · CC#1 · 2026-10-03 · encargo Lenovo «cada foto viaja con todo su contexto» punto 5.
 *
 * Lógica PURA (sin red, sin `this`, sin `require`): la usan el flujo del brief, el flujo de la pieza y las pruebas · se pega entera en los nodos Code de n8n (estilo `var` + `function`).
 *
 * 🔴 ESTRUCTURAL, NUNCA POR CLIENTE: el trato se LEE del manual de marca (campo explícito o lo que dice su descripción de voz) o de la ficha del cliente; sólo si ninguno lo dice se usa, DECLARADO
 * y de baja confianza, el trato habitual del país de la ficha. Si no hay nada, queda «no_definido» y NO se comprueba nada (no se inventa una regla).
 * El detector reconoce las FORMAS del español (conjugación regular del voseo y del tuteo sobre verbos de uso comercial), no frases ni clientes.
 */
function sinTildes(s) {
  return String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
}

var TRATOS = ['tu', 'vos', 'usted']

/** valor explícito → 'tu' | 'vos' | 'usted' | null */
function tratoDeValor(v) {
  var t = sinTildes(v).trim()
  if (!t) return null
  if (/^(tu|tuteo|tutear)$/.test(t)) return 'tu'
  if (/^(vos|voseo|vosear)$/.test(t)) return 'vos'
  if (/^(usted|ustedeo|formal)$/.test(t)) return 'usted'
  return null
}

// lo que dice un TEXTO de voz sobre el trato, respetando las negaciones: «Tutea siempre (tú/sabes/pides — nunca vos)» ⇒ tú, y vos queda NEGADO
var MENCION = {
  tu: /\b(tutea\w*|tuteo|tutear|tu)\b/g,
  vos: /\b(vos|voseo|vosea\w*|vosear)\b/g,
  usted: /\b(usted|ustedeo|ustedea\w*|trato formal)\b/g,
}
function mencionesDelTexto(texto) {
  var t = sinTildes(texto)
  var out = { tu: 0, vos: 0, usted: 0, negados: [] }
  TRATOS.forEach(function (k) {
    var re = new RegExp(MENCION[k].source, 'g')
    var m
    while ((m = re.exec(t)) !== null) {
      // «tu» a secas es un posesivo muy común («tu puerta»): sólo cuenta si va pegado a una indicación de trato (tú/sabes/pides …) o es tuteo/tutea
      if (m[1] === 'tu' && !/tu\s*[\/·,]\s*(sabes|pides|tienes|quieres|puedes|eres|vienes)/.test(t.slice(m.index, m.index + 30))) continue
      var antes = t.slice(Math.max(0, m.index - 24), m.index)
      if (/\b(nunca|jamas|no|ni|sin|evita|evitar|evites)\s+(\w+\s+){0,2}$/.test(antes)) out.negados.push(k)
      else out[k] += 1
    }
  })
  return out
}

// el trato habitual del país SÓLO cuando nadie lo dijo (baja confianza · se declara) · sin país conocido no hay default
var POR_PAIS = { argentina: 'vos', uruguay: 'vos', paraguay: 'vos', ecuador: 'tu', mexico: 'tu', peru: 'tu', chile: 'tu', espana: 'tu', bolivia: 'tu', venezuela: 'tu', panama: 'tu', 'costa rica': 'usted' }

/**
 * `manual` = { voice_description, writing_style, tone_guidelines } · `ficha` = { config, country, market }
 * → { trato: 'tu'|'vos'|'usted'|'no_definido'|'conflicto', fuente, evidencia }
 */
function resolverTrato(manual, ficha) {
  var m = manual || {}
  var f = ficha || {}
  var tg = m.tone_guidelines && typeof m.tone_guidelines === 'object' ? m.tone_guidelines : {}
  var cfg = f.config && typeof f.config === 'object' ? f.config : {}
  var voz = cfg.voz && typeof cfg.voz === 'object' ? cfg.voz : {}
  var explicitos = [
    ['manual.tone_guidelines.trato', tg.trato], ['manual.tone_guidelines.tratamiento', tg.tratamiento], ['manual.tone_guidelines.address_form', tg.address_form],
    ['ficha.config.voz.trato', voz.trato], ['ficha.config.trato', cfg.trato],
  ]
  for (var i = 0; i < explicitos.length; i++) {
    var v = tratoDeValor(explicitos[i][1])
    if (v) return { trato: v, fuente: explicitos[i][0].indexOf('manual') === 0 ? 'manual' : 'ficha', evidencia: explicitos[i][0] + ' = «' + explicitos[i][1] + '»' }
  }
  var texto = [m.voice_description, m.writing_style, m.tone_guidelines && Object.keys(tg).length ? JSON.stringify(tg) : ''].filter(Boolean).join(' · ')
  if (texto) {
    var me = mencionesDelTexto(texto)
    var pos = TRATOS.filter(function (k) { return me[k] > 0 })
    if (pos.length === 1) return { trato: pos[0], fuente: 'manual', evidencia: 'la descripción de voz del manual lo dice (' + pos[0] + (me.negados.length ? ' · niega ' + me.negados.join(', ') : '') + ')' }
    if (pos.length > 1) return { trato: 'conflicto', fuente: 'manual', evidencia: 'la descripción de voz menciona más de un trato (' + pos.join(' y ') + ') sin negar ninguno · no se puede elegir' }
  }
  var pais = sinTildes(f.country).trim() || sinTildes(String(f.market || '').split(/[·|,;\/]/).pop()).trim()
  if (pais && POR_PAIS[pais]) return { trato: POR_PAIS[pais], fuente: 'default_por_pais', evidencia: 'ni el manual ni la ficha lo dicen: se usa el trato habitual de «' + pais + '» (BAJA confianza · conviene ponerlo en el manual)' }
  return { trato: 'no_definido', fuente: 'ninguna', evidencia: 'ni el manual ni la ficha dicen el trato y no hay país conocido · NO se comprueba' }
}

// ───────────────────────────── las formas ─────────────────────────────
// verbos de uso comercial/llamado a la acción (infinitivos regulares en la conjugación del voseo) · es LENGUA, no clientes
var VERBOS = ('pedir mandar escribir enviar llamar contar avisar venir hacer comprar probar reservar consultar mirar seguir sumar unir descubrir elegir disfrutar compartir ordenar encargar contactar visitar ' +
  'decir tener querer poder saber vivir sentir pasar dejar traer llevar buscar conocer escuchar preguntar responder recibir pagar cambiar usar armar crear ahorrar aprovechar animar inscribir registrar ' +
  'suscribir invitar acompañar agendar cotizar solicitar averiguar entrar ingresar escoger pensar imaginar atreverse quedar poner salir').split(' ')
var CLITICOS = ['', 'lo', 'la', 'los', 'las', 'le', 'les', 'me', 'nos', 'te', 'se']

function radical(inf) { return inf.replace(/se$/, '').slice(0, -2) }
function vocalTematica(inf) { var f = inf.replace(/se$/, ''); return f.slice(-2, -1) === 'a' || /ar$/.test(f) ? 'a' : /er$/.test(f) ? 'e' : 'i' }
var ACENTO = { a: 'á', e: 'é', i: 'í' }

function formasVoseo() {
  var s = {}
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + ACENTO[v]] = true // pedí · mandá · escribí
    CLITICOS.slice(1).forEach(function (c) { s[r + v + c] = true }) // pedilo · mandalo · escribinos
    s[r + ACENTO[v] + 's'] = true // pedís · mandás · tenés (voseo presente)
    if (v === 'e') s[r + 'és'] = true
  })
  ;['sos', 'tenés', 'querés', 'podés', 'sabés', 'venís', 'hacés', 'decís', 'ponés', 'salís', 'vení', 'poné', 'hacé', 'decí', 'tené', 'salí'].forEach(function (w) { s[w] = true })
  return s
}
// el tuteo: pronombre, presente 2.ª persona regular y el imperativo con clítico acentuado («pídelo», «mándanos»)
function acentuarUltimaVocal(stem) {
  var i = stem.length - 1
  while (i >= 0 && !/[aeiou]/.test(stem[i])) i--
  if (i < 0) return stem
  return stem.slice(0, i) + ({ a: 'á', e: 'é', i: 'í', o: 'ó', u: 'ú' })[stem[i]] + stem.slice(i + 1)
}
function formasTuteo() {
  var s = {}
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + (v === 'a' ? 'as' : 'es')] = true // mandas · escribes · tienes(irregular: ver abajo)
    var imp = r + (v === 'a' ? 'a' : 'e')
    CLITICOS.slice(1).forEach(function (c) { s[acentuarUltimaVocal(imp) + c] = true }) // mándalo · escríbenos
  })
  ;['eres', 'tienes', 'quieres', 'puedes', 'sabes', 'vienes', 'haces', 'dices', 'pides', 'pídelo', 'pídela', 'pídenos', 'ven', 'haz', 'dime', 'cuéntanos', 'escríbenos', 'avísanos', 'llámanos', 'mándanos', 'tú'].forEach(function (w) { s[w] = true })
  return s
}
// formas de usted: pronombre (no «ustedes», que es plural neutro) y el imperativo/presente formal regular
function formasUsted() {
  var s = { usted: true }
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + (v === 'a' ? 'e' : 'a')] = true // mande · escriba
    CLITICOS.slice(1).forEach(function (c) { s[acentuarUltimaVocal(r + (v === 'a' ? 'e' : 'a')) + c] = true })
  })
  return s
}
var VOSEO = formasVoseo(), TUTEO = formasTuteo(), USTED = formasUsted()
// palabras que coinciden por casualidad con una forma generada y NO son esa forma (sustantivos y adverbios comunes)
var FALSOS = { mas: 1, pase: 1, deje: 1, cree: 1, vea: 1, sienta: 1, nos: 1 }

/** las palabras (con tilde) de un texto, en minúscula */
function palabras(texto) { return String(texto || '').toLowerCase().match(/[a-záéíóúüñ]+/g) || [] }

/** las formas de cada trato que aparecen en el texto: { vos: [palabras], tu: [...], usted: [...] } */
function formasDeTrato(texto) {
  var out = { vos: [], tu: [], usted: [] }
  var add = function (k, w) { if (out[k].indexOf(w) === -1) out[k].push(w) }
  palabras(texto).forEach(function (w) {
    if (w === 'vos') add('vos', w)
    else if (VOSEO[w]) add('vos', w)
    else if (TUTEO[w]) add('tu', w)
    else if (USTED[w] && !FALSOS[w]) add('usted', w)
  })
  return out
}

/**
 * ¿el texto respeta el trato de la marca? → [{ chequeo, detalle, fatal:false }]
 * `donde` = «la pieza» · «el brief». Sin trato definido (o en conflicto) NO se comprueba y se dice.
 */
function chequearTrato(resolucion, texto, donde) {
  var r = resolucion || { trato: 'no_definido' }
  var d = donde || 'el texto'
  if (r.trato === 'no_definido' || r.trato === 'conflicto') return []
  var formas = formasDeTrato(texto)
  var otros = TRATOS.filter(function (k) { return k !== r.trato })
  var hallados = []
  otros.forEach(function (k) { formas[k].forEach(function (w) { hallados.push({ w: w, k: k }) }) })
  // el usted «mande/llame» coincide con presentes de 3.ª persona: sólo se avisa si el trato de la marca NO es usted y no hay forma más clara
  if (!hallados.length) return []
  var nombre = { tu: 'tuteo', vos: 'voseo', usted: 'usted' }
  return [{
    chequeo: 'trato_distinto_al_del_cliente',
    detalle: d + ' trae formas de otro trato: ' + hallados.slice(0, 6).map(function (x) { return '«' + x.w + '» (' + nombre[x.k] + ')' }).join(' · ') + ' y el trato de la marca es ' + nombre[r.trato] + ' (' + r.fuente + ': ' + r.evidencia + ')',
    fatal: false,
  }]
}

/** el bloque para el pedido/brief: el trato y de dónde sale · y qué hacer si otro texto (el brief) trae otro */
function bloqueDeTrato(resolucion) {
  var r = resolucion || { trato: 'no_definido', fuente: 'ninguna', evidencia: '' }
  var nombre = { tu: 'TÚ (tuteo)', vos: 'VOS (voseo)', usted: 'USTED' }
  if (r.trato === 'no_definido') return 'F) EL TRATO. El sistema NO sabe qué trato (tú · vos · usted) usa esta marca: ni el manual ni la ficha lo dicen. Escribe con el trato que use el manual en sus ejemplos y DECLÁRALO en «no_pude_cumplir» («trato no definido»).'
  if (r.trato === 'conflicto') return 'F) EL TRATO. El manual menciona más de un trato sin elegir (' + r.evidencia + '). No adivines: declara «trato en conflicto» en «no_pude_cumplir» y evita las formas de segunda persona cuando puedas.'
  return ['F) EL TRATO de esta marca es ' + nombre[r.trato] + ' (fuente: ' + r.fuente + ' · ' + r.evidencia + ').',
    '   Todo lo que se lee en la pieza (titular, texto, llamado) va en ese trato, sin mezclar. Si el brief trae formas de OTRO trato (por ejemplo una frase copiada de una conversación), NO las copies:',
    '   conviértelas al trato de la marca y dilo en «que_miro». El manual de marca manda sobre el brief.'].join('\n')
}


// ⑤ ARMAR EL CUERPO DEL PRODUCTOR · CC#1 · 2026-10-01 · 03-oct: CADA FOTO CON TODO SU CONTEXTO (texto · fecha · enlace · qué producto es) + la regla «sólo fotos del producto del brief» + el TRATO de la marca (tú · vos · usted) · lógica de fotos-contexto-logica.js y trato-logica.js pegada arriba por el constructor. Un solo agente (`campaign-brief-agent`) lee UN brief, mira las fotos reales del cliente, usa «mirar afuera» para lo que falte y ESCRIBE la pieza.
