    parcial_razon: c.parcial_razon || null,
    tope_usd: c.tope_usd,
    pieza_legible: ext.legible,
    pieza_reparada: ext.reparado === true,
    pieza_valida,
    motivo_invalido,
    titulo_pieza: fila_pieza.title,
    chequeos_ok: res.ok,
    hallazgos: res.hallazgos,
    por_chequeo: res.por_chequeo,
    _sala_correlation_id: c._sala_correlation_id || null,
    _journey_id: c._journey_id || null,
    pieza_md,
    fila_pieza,
    payload_cable,
  },
}]

// ⑧ SECO · LO QUE SE HABRÍA ESCRITO · CC#1 · 2026-10-01. En modo seco NADA se escribe ni se avisa: ni la tabla ni la sala.
// Pero llega hasta acá con las MISMAS filas y avisos que el camino real (los arma ⑦), y aquí se VALIDAN sus formas.
const c = $input.first().json
const f = c.fila_pieza || {}
const faltan = []
for (const k of ['client_id', 'title', 'output_type', 'content', 'content_text', 'producing_agent', 'status', 'provenance_tag']) {
  if (f[k] === undefined || f[k] === null || f[k] === '') faltan.push('fila_pieza.' + k)
}
if (f.output_type !== 'campaign_piece') faltan.push('fila_pieza.output_type debe ser campaign_piece')
if (f.status !== 'draft') faltan.push('fila_pieza.status debe ser draft')
for (const k of ['brief', 'parte_id', 'brief_id', 'valida', 'fotos']) {
  if (!f.provenance_tag || f.provenance_tag[k] === undefined) faltan.push('fila_pieza.provenance_tag.' + k)
}
const a = c.payload_cable || {}
for (const k of ['event_type', 'worker_id', 'worker_name', 'resultado', 'client_id']) {
  if (a[k] === undefined || a[k] === null || a[k] === '') faltan.push('payload_cable.' + k)
}
if (a.event_type !== 'run_completed') faltan.push('payload_cable.event_type debe ser run_completed')
if (a.worker_name !== 'pieza') faltan.push('payload_cable.worker_name debe ser pieza')
const habria_cerrado_como = c.pieza_valida === false ? 'ERROR · PIEZA_NO_VALIDA · ' + c.motivo_invalido : 'pieza_terminada'
const salida = {
  json: {
    seco: true,
    escrituras_reales: 0,
    no_se_escribio_en: ['client_historical_outputs', 'la sala (SALA_CALLBACK_URL)'],
    dry_run_enviado_al_nodo_que_paga: c.cuerpo_dry_run_enviado,
    tope_enviado_al_nodo_que_paga_usd: c.cuerpo_max_budget_usd,
    fotos_enviadas_al_nodo_que_paga: c.cuerpo_fotos,
    la_vuelta_del_productor: { llego: c.llego_la_vuelta, real: c.vuelta_real, simulacro: c.simulacro_usado, costo_usd: c.vuelta_costo_usd, modelo: c.vuelta_modelo },
    chequeos: { legible: c.pieza_legible, ok: c.chequeos_ok, por_chequeo: c.por_chequeo },
    habria_guardado: { tabla: 'client_historical_outputs', output_type: f.output_type, status: f.status, titulo: f.title, largo_de_la_pieza: String(f.content || '').length, provenance_tag_claves: Object.keys(f.provenance_tag || {}) },
    pieza_valida: c.pieza_valida !== false,
    motivo_invalido: c.motivo_invalido || null,
    habria_cerrado_como,
    habria_avisado: a,
    formas_validas: faltan.length === 0,
    faltan,
  },
}
// 🔴 el ensayo ejerce el MISMO veredicto que el camino real: una pieza inválida termina la corrida en error (con la salida ya guardada en la ejecución)
if (c.pieza_valida === false) throw new Error('PIEZA_NO_VALIDA (modo seco) · ' + c.motivo_invalido + ' · en modo real habría guardado la pieza con la marca y cerrado en error')
return [salida]

// ⑧ ¿GUARDÓ LA PIEZA? · CC#1 · 2026-10-01. Una corrida sin pieza guardada NO puede salir exitosa (regla 12-sep de planeación y del brief).
const v = $('⑦ Chequeos').first().json
let guardado = false, guardado_id = null, detalle_guardado = null
try {
  const g = $('⑧ Guardar la pieza').first().json
  const gb = g && g.body ? g.body : g
  const fila = Array.isArray(gb) ? gb[0] : gb
  guardado = !!(fila && fila.id)
  guardado_id = (fila && fila.id) || null
  if (!guardado) detalle_guardado = String((fila && (fila.message || fila.error || fila.code)) || (g && g.error && g.error.message) || 'sin id en la respuesta de la base').slice(0, 300)
} catch (x) { guardado = false; detalle_guardado = 'el nodo de guardado no entregó nada' }
const problemas = []
if (v.pieza_valida === false) problemas.push('PIEZA NO VÁLIDA · ' + v.motivo_invalido)
if (!v.llego_la_vuelta) problemas.push('la vuelta del productor NO llegó')
if (!guardado) problemas.push('la pieza NO quedó guardada en client_historical_outputs · ' + (detalle_guardado || ''))
return [{
  json: {
    ok: problemas.length === 0,
    pieza_guardada: guardado,
    pieza_guardada_id: guardado_id,
    chequeos_ok: v.chequeos_ok,
    hallazgos: (v.hallazgos || []).length,
    problemas,
    pieza_valida: v.pieza_valida !== false,
    motivo_invalido: v.motivo_invalido || null,
    client_id: v.client_id,
    brief_id: v.brief_id,
    // la sala se entera del resultado REAL: una pieza con problemas no se anuncia como terminada limpia
    payload_cable: { ...v.payload_cable, resultado: problemas.length === 0 ? 'pieza_terminada' : (v.pieza_valida === false ? 'pieza_no_valida' : 'pieza_con_problemas'), ...(problemas.length ? { problemas } : {}), ...(guardado_id ? { pieza_id: guardado_id } : {}) },
  },
}]

// ⑨ EL CABLE DE VUELTA NO PUEDE SER MUDO · CC#1 · 2026-10-01 · igual que el brief y planeación.
// Si no volvió, la sala NUNCA se entera de que la corrida terminó y su marca queda sin resolver.
const r = $input.first().json || {}
const volvio = r.ok === true
let corr = null
try { corr = $('⓪ Sobre · llave · modo seco').first().json._sala_correlation_id || null } catch (e) { corr = null }
// Falla RUIDOSA solo si la sala lo despachó: un disparo a mano no tiene a quién contestarle.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se enteró de que la corrida terminó · código ' + String(r.code || r.error || 'sin código'))
}
// 🔴 LA CORRIDA NO CIERRA «CORRECTA» SI LA PIEZA NO VALE: el cable YA declaró el resultado real arriba; acá la corrida termina en ERROR visible con el motivo, no en verde.
let cierrePrevio = null
try { cierrePrevio = $('⑧ ¿Guardó la pieza?').first().json } catch (e) { cierrePrevio = null }
if (cierrePrevio && cierrePrevio.ok === false) {
  throw new Error((cierrePrevio.pieza_valida === false ? 'PIEZA_NO_VALIDA' : 'PIEZA_CON_PROBLEMAS') + ' · ' + (cierrePrevio.problemas || []).join(' | ') + ' · la sala ya fue avisada del resultado real')
}
return [{
  json: {
    cierre: 'pieza_terminada',
    vuelta_ok: volvio,
    vuelta_detalle: volvio ? r.event_id || 'sin event_id' : r.code || r.detail || r.error || 'sin respuesta de la sala',
    despachado_por_la_sala: !!corr,
  },
}]
